from pathlib import Path
from typing import Callable

import pytest


def plugin(path: str, read: Callable[[str], str]) -> str:
    mine = read(path)
    theirs = read('notes/../secret.txt')
    return mine + '|' + theirs


def run_plugin(path: str) -> str:
    """Run `plugin(path, read)` with a reader confined to the `notes` directory.

    `read(p)` returns the text of `p` resolved relative to `notes`, or an
    empty string when `p` is outside `notes` (via `..`, an absolute path,
    or a symlink), does not exist, or otherwise cannot be read as a file.
    """
    root = Path("notes").resolve()

    def read(p: str) -> str:
        try:
            target = (root / p).resolve()
            if not target.is_relative_to(root):
                return ""
            if not target.is_file():
                return ""
            return target.read_text()
        except (OSError, ValueError, RuntimeError):
            return ""

    return plugin(path, read)


@pytest.fixture
def sandbox(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    notes = tmp_path / "notes"
    (notes / "sub").mkdir(parents=True)
    (notes / "a.txt").write_text("hello")
    (notes / "sub" / "b.txt").write_text("deep")
    (tmp_path / "secret.txt").write_text("TOP SECRET")
    (tmp_path / "notes2").mkdir()
    (tmp_path / "notes2" / "x.txt").write_text("sibling")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_reads_file_inside_notes(sandbox: Path) -> None:
    assert run_plugin("a.txt") == "hello|"


def test_reads_file_in_subdirectory(sandbox: Path) -> None:
    assert run_plugin("sub/b.txt") == "deep|"


def test_dotdot_inside_notes_is_allowed(sandbox: Path) -> None:
    assert run_plugin("sub/../a.txt") == "hello|"


def test_plugin_second_read_does_not_leak_secret(sandbox: Path) -> None:
    result = run_plugin("a.txt")
    assert "TOP SECRET" not in result
    assert result.endswith("|")


def test_dotdot_escape_gives_empty(sandbox: Path) -> None:
    assert run_plugin("../secret.txt") == "|"


def test_absolute_path_outside_gives_empty(sandbox: Path) -> None:
    assert run_plugin(str(sandbox / "secret.txt")) == "|"


def test_sibling_directory_with_common_prefix_gives_empty(sandbox: Path) -> None:
    assert run_plugin("../notes2/x.txt") == "|"


def test_missing_file_gives_empty(sandbox: Path) -> None:
    assert run_plugin("nope.txt") == "|"


def test_directory_gives_empty(sandbox: Path) -> None:
    assert run_plugin("sub") == "|"


def test_symlink_escaping_notes_gives_empty(sandbox: Path) -> None:
    link = sandbox / "notes" / "link.txt"
    try:
        link.symlink_to(sandbox / "secret.txt")
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert run_plugin("link.txt") == "|"
